const fs = require('fs');

function fnv1a(bytes) {
  let hash = 0x811c9dc5;
  for (let i = 0; i < bytes.length; i++) {
    hash ^= bytes[i];
    hash = (hash * 16777619) >>> 0;  // Keep as 32-bit unsigned
  }
  return hash.toString(16).padStart(8, '0');
}

const a = fs.readFileSync('data/files/a.txt');
const b = fs.readFileSync('data/files/b.txt');

console.log('a.txt:', fnv1a(a), '(expected e37d9473)');
console.log('b.txt:', fnv1a(b), '(expected 784f5257)');
"
