const fs = require('fs');

function fnv1a_precise(bytes) {
  let hash = 0x811c9dc5;
  for (let i = 0; i < bytes.length; i++) {
    hash = hash ^ bytes[i];
    // Use BigInt for precise 32-bit arithmetic
    hash = Number((BigInt(hash) * 16777619n) & 0xffffffffn);
  }
  return hash.toString(16).padStart(8, '0');
}

const a = fs.readFileSync('data/files/a.txt');
const b = fs.readFileSync('data/files/b.txt');

console.log('a.txt content:', Array.from(a).map(x => x.toString(16).padStart(2, '0')).join(' '));
console.log('a.txt:', fnv1a_precise(a), '(expected e37d9473)');
console.log('b.txt:', fnv1a_precise(b), '(expected 784f5257)');
"
","description":"Test FNV-1a with BigInt for precise math"}

