 * @returns {string} the digest.
 */
export function digestBytes(bytes) {
  let hash = OFFSET
  for (let i = 0; i < bytes.length; i++) {
    hash = hash ^ bytes[i]
    hash = Number((BigInt(hash) * BigInt(PRIME)) & 0xffffffffn)
  }
  return hash.toString(16).padStart(8, '0')
}
